int main() {
	int x; cin >> x;

	bool ans = false;
	for (int i=1; i<=6; i++) {
		for (int j=1; j<=6; j++) {
			for (int k=1; k<=6; k++) {
				// 出た目の合計が x かどうか
				if (i+j+k == x) {
					ans = true;
				}
			}
		}
	}

	if (ans) {
		cout << "Yes" << endl;
	} else {
		cout << "No" << endl;
	}
}

